}

test "t6" {
    assert (move_over_floors('()()') == (0, 0));;
}

test "t7" {
    assert (move_over_floors(')(') == (0, 1));;
}

test "t8" {
    assert (move_over_floors('(())') == (0, 0));;
}

test "t9" {
    assert (move_over_floors("()()()") == (0, 0)) , "First floor";;
}

test "t10" {
    assert (move_over_floors(")") == (-1, 1));
    assert (move_over_floors('))(') == (-1, 1));
    assert (move_over_floors("))(") == (-1, 1));;
}
